		"<datasource>\n  <password>Sup3rSecret</password>\n  <url>jdbc:postgresql://db.company/app</url>\n</datasource>\n",
		"export AWS_ACCESS_KEY_ID=AKIAIOSFODNN7EXAMPLE\nexport REGION=eu-west-1\n",
	} {
		masked, _ := Sanitize(input)
