	}
	if strings.Contains(safe, "super-secret-value") || strings.Contains(safe, "AKIA1234567890123456") {
		t.Fatalf("secret remained: %q", safe)
	}
}

func TestSanitizeKnownTokensDSNAndEntropyWithoutMaskingCommitHashes(t *testing.T) {
